-- 2. AAMC content categories, official wording
-- ────────────────────────────────────────────────────────────
-- 4A (35 concepts)
SELECT id, 'Translational motion, forces, work, energy, and equilibrium in living systems' FROM public.concepts WHERE slug IN ('ACCELERATION', 'CENTER_OF_MASS_AND_GRAVITY', 'CHEMICAL_POTENTIAL_ENERGY', 'CIRCULAR_MOTION_AND_CENTRIPETAL_FORCE', 'CONSERVATION_OF_MECHANICAL_ENERGY', 'CONSERVATIVE_FORCES', 'DISPLACEMENT_VELOCITY_AND_SPEED', 'ELASTIC_POTENTIAL_ENERGY', 'ENERGY_AND_ITS_FORMS', 'FORCE', 'FREE_BODY_DIAGRAMS', 'FREE_FALL_AND_TERMINAL_VELOCITY', 'FRICTION', 'GRAVITATIONAL_POTENTIAL_ENERGY', 'INCLINED_PLANE_FORCE_COMPONENTS', 'INCLINED_PLANE_MECHANICAL_ADVANTAGE', 'KINEMATIC_EQUATIONS', 'KINETIC_ENERGY', 'MACHINE_EFFICIENCY', 'MASS_AND_WEIGHT', 'NEWTONS_FIRST_LAW_AND_INERTIA', 'NEWTONS_SECOND_LAW', 'NEWTONS_THIRD_LAW', 'NON_CONSERVATIVE_FORCES', 'POWER', 'PRESSURE_VOLUME_WORK', 'PROJECTILE_MOTION', 'PULLEY_SYSTEMS', 'SIMPLE_MACHINES_AND_MECHANICAL_ADVANTAGE', 'TORQUE', 'TOTAL_MECHANICAL_ENERGY', 'TRANSLATIONAL_AND_ROTATIONAL_EQUILIBRIUM', 'UNIVERSAL_GRAVITATION', 'WORK', 'WORK_ENERGY_THEOREM');

