SELECT id, 'Importance of fluids for the circulation of blood, gas movement, and gas exchange' FROM public.concepts WHERE slug IN ('ABSOLUTE_AND_GAUGE_PRESSURE', 'ARCHIMEDES_PRINCIPLE_AND_BUOYANT_FORCE', 'BERNOULLIS_EQUATION', 'COHESION_ADHESION_AND_SURFACE_TENSION', 'CONTINUITY_EQUATION_AND_FLOW_RATE', 'DENSITY_AND_SPECIFIC_GRAVITY', 'FLOTATION_AND_DISPLACEMENT', 'FLUIDS_AND_THEIR_PROPERTIES', 'HYDROSTATIC_PRESSURE', 'LAMINAR_AND_TURBULENT_FLOW', 'PASCALS_PRINCIPLE_AND_HYDRAULICS', 'POISEUILLES_LAW_AND_FLOW_RESISTANCE', 'PRESSURE', 'VENTURI_EFFECT_AND_FLOW_MEASUREMENT', 'VISCOSITY_AND_VISCOUS_DRAG');

-- 4C (30 concepts)
SELECT id, 'Electrochemistry and electrical circuits and their elements' FROM public.concepts WHERE slug IN ('CAPACITANCE', 'CAPACITORS_IN_SERIES_AND_PARALLEL', 'CHARGED_PARTICLE_MOTION_IN_A_MAGNETIC_FIELD', 'CIRCUIT_MEASURING_INSTRUMENTS', 'CONDUCTORS_INSULATORS_AND_CONDUCTIVITY', 'CONVENTIONAL_CURRENT_AND_CHARGE_CARRIERS', 'COULOMBS_LAW', 'DIELECTRICS', 'ELECTRICAL_POWER_DISSIPATION', 'ELECTRIC_CHARGE', 'ELECTRIC_CURRENT', 'ELECTRIC_DIPOLES', 'ELECTRIC_FIELD', 'ELECTRIC_POTENTIAL', 'ELECTRIC_POTENTIAL_ENERGY', 'ELECTROMOTIVE_FORCE_AND_TERMINAL_VOLTAGE', 'ENERGY_STORED_IN_A_CAPACITOR', 'EQUIPOTENTIAL_LINES', 'KIRCHHOFFS_RULES', 'LORENTZ_FORCE', 'MAGNETIC_FIELDS_AND_SOURCES', 'MAGNETIC_FIELD_OF_A_CURRENT', 'MAGNETIC_FORCE_ON_CHARGES_AND_CURRENTS', 'MAGNETIC_MATERIALS', 'OHMS_LAW', 'PARALLEL_PLATE_CAPACITORS', 'RESISTANCE_AND_RESISTORS', 'RESISTIVITY_AND_WIRE_GEOMETRY', 'RESISTORS_IN_PARALLEL', 'RESISTORS_IN_SERIES');

-- 4D (39 concepts)
SELECT id, 'How light and sound interact with matter' FROM public.concepts WHERE slug IN ('BEAT_FREQUENCY', 'DAMPING', 'DECIBEL_SCALE_AND_ATTENUATION', 'DIFFRACTION', 'DISPERSION', 'DOPPLER_EFFECT', 'ELECTROMAGNETIC_WAVE_STRUCTURE', 'FREQUENCY_PERIOD_AND_ANGULAR_FREQUENCY', 'LENSES_AND_IMAGE_FORMATION', 'LENS_ABERRATION', 'LENS_POWER_AND_COMBINATIONS', 'LIGHT_INTERFERENCE', 'MIRRORS_AND_IMAGE_FORMATION', 'OBJECT_DISTANCE_AND_IMAGE_CHARACTERISTICS', 'OPTICAL_SIGN_CONVENTIONS', 'PITCH_AND_LOUDNESS', 'POLARIZATION', 'REAL_VERSUS_VIRTUAL_IMAGES', 'REFLECTION', 'REFRACTION_AND_SNELLS_LAW', 'RESONANCE_AND_NATURAL_FREQUENCY', 'SHOCK_WAVES', 'SLIT_AND_GRATING_PATTERNS', 'SOUND_AS_A_MECHANICAL_WAVE', 'SPEED_OF_LIGHT_AND_THE_WAVE_EQUATION', 'SPEED_OF_SOUND_IN_MEDIA', 'STANDING_WAVES', 'STANDING_WAVES_IN_STRINGS_AND_PIPES', 'SUPERPOSITION_AND_INTERFERENCE', 'THE_ELECTROMAGNETIC_SPECTRUM', 'THIN_FILM_INTERFERENCE', 'THIN_LENS_EQUATION_AND_MAGNIFICATION', 'TOTAL_INTERNAL_REFLECTION', 'TRANSVERSE_AND_LONGITUDINAL_WAVES', 'ULTRASOUND', 'VISIBLE_LIGHT_AND_COLOR', 'WAVE_ANATOMY_AND_AMPLITUDE', 'WAVE_INTENSITY', 'WAVE_SPEED_EQUATION');

-- 4E (11 concepts)  -- already in the vocabulary, reused
SELECT id, 'Atoms, nuclear decay, electronic structure, and atomic chemical behavior' FROM public.concepts WHERE slug IN ('ALPHA_DECAY', 'BETA_DECAY', 'FLUORESCENCE', 'FUNDAMENTAL_FORCES_AND_THE_NUCLEAR_FORCES', 'MASS_DEFECT_AND_NUCLEAR_BINDING_ENERGY', 'MAXIMUM_PHOTOELECTRON_KINETIC_ENERGY', 'NUCLEAR_FUSION_AND_FISSION', 'PHOTOELECTRIC_EFFECT', 'RADIOACTIVE_DECAY_MODES', 'RADIOACTIVE_HALF_LIFE', 'WORK_FUNCTION_AND_THRESHOLD_FREQUENCY');

-- 5E (7 concepts)
SELECT id, 'Principles of chemical thermodynamics and kinetics' FROM public.concepts WHERE slug IN ('FIRST_LAW_OF_THERMODYNAMICS', 'HEAT_TRANSFER_MECHANISMS', 'REVERSIBLE_AND_IRREVERSIBLE_PROCESSES', 'SECOND_LAW_OF_THERMODYNAMICS', 'STATE_FUNCTIONS_AND_PATH_FUNCTIONS', 'THERMAL_EXPANSION', 'THERMODYNAMIC_PROCESSES');

-- Pressure-volume work is thermodynamic (5E) but is also taught in the
-- physics energy and work chapter, so it genuinely spans both.
SELECT id, 'Translational motion, forces, work, energy, and equilibrium in living systems', FALSE FROM public.concepts WHERE slug = 'PRESSURE_VOLUME_WORK'
ON CONFLICT DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- 3. The 4 new QUANTITATIVE objects
--
-- Deliberately NO section, discipline or category. Motion & Forces opens with
-- 14 cards of vector mathematics before any physics appears at card 15. A
-- student who cannot resolve components fails projectile, inclined-plane,
-- torque and electric-field questions alike; filed as physics content that
-- reads as four separate weaknesses instead of one root cause.
-- ────────────────────────────────────────────────────────────

-- ────────────────────────────────────────────────────────────
-- 4. Widening existing concepts, decided one at a time
--
-- Nine concepts gain PHYSICS as a SECONDARY discipline: their physics cards
-- are the evidence they are taught here too. All nine already sit in
-- CHEM_PHYS, so no section changes.
--
-- The two spectroscopy objects additionally gain 4D, because AAMC examines
-- absorption spectra under "How light and sound interact with matter" as well
-- as under organic structure. Their organic chemistry rows are untouched.
--
-- DELIBERATELY NOT WIDENED: the categories of the five thermodynamics objects.
-- They carry none at all, which is a pre-existing gap covered by the separate
-- uncategorized audit. Filling them here would be a guess dressed as a fact.
-- ────────────────────────────────────────────────────────────
SELECT id, 'PHYSICS', 'SECONDARY' FROM public.concepts WHERE canonical_name IN ('Quantization, Bohr & Spectra', 'Isotopes & Atomic Weight', 'Infrared Spectroscopy', 'Ultraviolet-Visible Spectroscopy', 'Heat, Temperature and Thermal Equilibrium', 'Calorimetry and Heat Capacity', 'Phase Changes and Latent Heat', 'Entropy', 'Thermodynamics: Systems & Free Energy')
ON CONFLICT DO NOTHING;

SELECT id, 'How light and sound interact with matter', FALSE FROM public.concepts WHERE canonical_name IN ('Infrared Spectroscopy', 'Ultraviolet-Visible Spectroscopy')
ON CONFLICT DO NOTHING;

-- ────────────────────────────────────────────────────────────
-- 5. The 444 card mappings, one PRIMARY each
-- ────────────────────────────────────────────────────────────

-- ────────────────────────────────────────────────────────────
-- 6. Verification, inside the transaction. Anything unexpected is a reason to
--    ROLLBACK rather than COMMIT.
-- ────────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.concepts)                                    AS objects,       -- 846
  (SELECT count(*) FROM public.concepts WHERE object_type='CONTENT')        AS content,       -- 814
  (SELECT count(*) FROM public.concepts WHERE object_type='REASONING')      AS reasoning,     -- 12
  (SELECT count(*) FROM public.concepts WHERE object_type='QUANTITATIVE')   AS quantitative,  -- 20
  (SELECT count(*) FROM public.flashcard_concepts)                          AS card_mappings, -- 1183
  (SELECT count(*) FROM public.question_concepts)                           AS q_mappings;    -- 2659 unchanged

-- Every physics card mapped exactly once. Expect 444 and 0.
SELECT count(*) AS physics_cards, count(*) FILTER (WHERE n <> 1) AS not_exactly_one
FROM (SELECT f.id, count(fc.concept_id) AS n
      FROM public.flashcards f
      JOIN public.flashcard_decks d ON d.id=f.deck_id AND d.section='physics'
      LEFT JOIN public.flashcard_concepts fc ON fc.flashcard_id=f.id
      GROUP BY f.id) t;

-- No QUANTITATIVE object carries disciplinary taxonomy. Expect zero rows.
SELECT 'quantitative carries taxonomy' AS problem, c.slug FROM public.concepts c
WHERE c.object_type='QUANTITATIVE' AND (
  EXISTS (SELECT 1 FROM public.concept_sections s WHERE s.concept_id=c.id) OR
  EXISTS (SELECT 1 FROM public.concept_disciplines d WHERE d.concept_id=c.id) OR
  EXISTS (SELECT 1 FROM public.concept_content_categories k WHERE k.concept_id=c.id));

-- No QUANTITATIVE object reached question_concepts. Expect zero rows.
SELECT 'quantitative in question_concepts' AS problem, count(*)
FROM public.question_concepts qc JOIN public.concepts c ON c.id=qc.concept_id
WHERE c.object_type <> 'CONTENT';

-- The five new categories landed. Expect 4A/4B/4C/4D/5E with non-zero counts.
SELECT content_category, count(*) FROM public.concept_content_categories
WHERE content_category IN ('Translational motion, forces, work, energy, and equilibrium in living systems', 'Importance of fluids for the circulation of blood, gas movement, and gas exchange', 'Electrochemistry and electrical circuits and their elements', 'How light and sound interact with matter', 'Principles of chemical thermodynamics and kinetics')
GROUP BY 1 ORDER BY 1;

-- Widening landed. Expect 9 and 2.
SELECT (SELECT count(*) FROM public.concept_disciplines WHERE discipline_code='PHYSICS' AND role='SECONDARY') AS widened_disc,
       (SELECT count(*) FROM public.concept_content_categories WHERE content_category='How light and sound interact with matter' AND is_primary=FALSE) AS widened_4d;

-- Nothing resolved to NULL, no provenance overstated. Expect 0 and 0.
SELECT (SELECT count(*) FROM public.flashcard_concepts WHERE concept_id IS NULL) AS unresolved,
       (SELECT count(*) FROM public.flashcard_concepts
         WHERE mapping_status='HUMAN_VALIDATED' OR source IN ('DETERMINISTIC','DETERMINISTIC_EXACT','LEGACY_EXACT')) AS overstated;

COMMIT;

-- ── ROLLBACK ────────────────────────────────────────────────────────────
-- DELETE FROM public.flashcard_concepts fc USING public.flashcards f, public.flashcard_decks d
--   WHERE fc.flashcard_id=f.id AND f.deck_id=d.id AND d.section='physics';
-- DELETE FROM public.concepts WHERE slug IN (the 141 slugs above);  -- taxonomy cascades
-- The widening in section 4 is additive; delete the PHYSICS SECONDARY rows and
-- the two 4D rows to undo it.
